{"schema":"# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: admin\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `admin` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  `address` varchar(255) DEFAULT NULL,\n  `role` varchar(50) DEFAULT 'admin',\n  `status` varchar(50) DEFAULT 'active',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 31 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: advocators\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `advocators` (\n  `advocator_id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(50) NOT NULL,\n  `middle_name` varchar(255) DEFAULT NULL,\n  `last_name` varchar(50) NOT NULL,\n  `gender` enum('male', 'female', 'other') NOT NULL,\n  `email` varchar(100) NOT NULL,\n  `mobile_number` varchar(20) NOT NULL,\n  `alternate_number` varchar(20) DEFAULT NULL,\n  `address` text NOT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  PRIMARY KEY (`advocator_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 16 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: appointment\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `appointment` (\n  `appointment_id` int(11) NOT NULL AUTO_INCREMENT,\n  `case_id` int(11) NOT NULL,\n  `date` date NOT NULL,\n  `time` time NOT NULL,\n  `note` text DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `judge_id` int(11) DEFAULT NULL,\n  PRIMARY KEY (`appointment_id`),\n  KEY `case_id` (`case_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 54 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: appointment_phonenumber_map\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `appointment_phonenumber_map` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `appointment_id` int(11) DEFAULT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `appointment_id` (`appointment_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 108 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: backups\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `backups` (\n  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  `backup_data` text DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `id` (`id`)\n) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: case_sub_type\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `case_sub_type` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `sub_type_name` varchar(255) NOT NULL,\n  `case_type` varchar(255) DEFAULT NULL,\n  `case_id` int(11) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `fk_case_type` (`case_type`(250)),\n  KEY `case_id` (`case_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 126 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: case_type\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `case_type` (\n  `id` int(11) DEFAULT NULL,\n  `case_type` varchar(255) DEFAULT NULL\n) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: cases\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `cases` (\n  `case_id` int(11) NOT NULL AUTO_INCREMENT,\n  `case_type` varchar(255) DEFAULT NULL,\n  `file_path` varchar(255) DEFAULT NULL,\n  `description` varchar(10000) DEFAULT NULL,\n  `policeStation` varchar(255) DEFAULT NULL,\n  `FIRNumber` varchar(255) DEFAULT NULL,\n  `FIRDate` date DEFAULT NULL,\n  `registrationDate` date DEFAULT NULL,\n  `assigned_judge` varchar(255) DEFAULT NULL,\n  `case_status` enum('running', 'closed') DEFAULT 'running',\n  `judge_decision` mediumtext DEFAULT NULL,\n  `is_paid` varchar(255) DEFAULT 'unpaid',\n  PRIMARY KEY (`case_id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 116 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: chat_logs\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `chat_logs` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `message` text NOT NULL,\n  `response` text NOT NULL,\n  `language` varchar(10) DEFAULT 'en',\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  PRIMARY KEY (`id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 3 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: clientreferences\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `clientreferences` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `client_id` int(11) DEFAULT NULL,\n  `reference_name` varchar(255) DEFAULT NULL,\n  `reference_mobile` varchar(20) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `client_id` (`client_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 58 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: clients\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `clients` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) DEFAULT NULL,\n  `middle_name` varchar(255) DEFAULT NULL,\n  `last_name` varchar(255) DEFAULT NULL,\n  `gender` enum('male', 'female') DEFAULT NULL,\n  `email` varchar(255) DEFAULT NULL,\n  `mobile_number` varchar(20) DEFAULT NULL,\n  `alternate_number` varchar(20) DEFAULT NULL,\n  `address` text DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 53 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: court_manager\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `court_manager` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  `address` varchar(255) DEFAULT NULL,\n  `role` varchar(50) DEFAULT 'court_manager',\n  `status` varchar(50) DEFAULT 'active',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 46 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: invoice_clerk\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `invoice_clerk` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  `address` varchar(255) DEFAULT NULL,\n  `role` varchar(50) DEFAULT 'invoice_clerk',\n  `status` varchar(50) DEFAULT 'active',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 55 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: invoice_items\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `invoice_items` (\n  `item_id` int(11) NOT NULL AUTO_INCREMENT,\n  `invoice_id` int(11) DEFAULT NULL,\n  `service` varchar(255) DEFAULT NULL,\n  `description` text DEFAULT NULL,\n  `amount` decimal(10, 2) DEFAULT NULL,\n  `paid_status` varchar(255) DEFAULT 'unpaid',\n  PRIMARY KEY (`item_id`),\n  KEY `fk_invoice_items_invoices` (`invoice_id`),\n  CONSTRAINT `fk_invoice_items_invoices` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`invoice_id`) ON DELETE CASCADE,\n  CONSTRAINT `invoice_items_ibfk_1` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`invoice_id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 142 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: invoices\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `invoices` (\n  `invoice_id` int(11) NOT NULL AUTO_INCREMENT,\n  `case_id` int(11) DEFAULT NULL,\n  `invoice_number` varchar(255) DEFAULT NULL,\n  `invoice_date` date DEFAULT NULL,\n  `due_date` date DEFAULT NULL,\n  `note` text DEFAULT NULL,\n  `total_amount` int(11) DEFAULT NULL,\n  `paid_status` enum('Paid', 'Unpaid', 'Partially Paid') DEFAULT NULL,\n  PRIMARY KEY (`invoice_id`),\n  KEY `case_id` (`case_id`),\n  CONSTRAINT `invoices_ibfk_1` FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 103 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: judge\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `judge` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  `address` varchar(255) DEFAULT NULL,\n  `role` varchar(50) DEFAULT 'judge',\n  `status` varchar(50) DEFAULT 'active',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 48 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: notifications\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `notifications` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `user_id` int(11) DEFAULT NULL,\n  `message` varchar(255) DEFAULT NULL,\n  `datetime` datetime NOT NULL DEFAULT current_timestamp(),\n  `status` int(11) DEFAULT 1,\n  PRIMARY KEY (`id`),\n  KEY `fk_user_id` (`user_id`),\n  CONSTRAINT `fk_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `notifications_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 248 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: otherdocumentcases\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `otherdocumentcases` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `case_id` int(11) DEFAULT NULL,\n  `file_path` varchar(255) DEFAULT NULL,\n  `description` text DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = InnoDB AUTO_INCREMENT = 41 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: petitioner_case_map\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `petitioner_case_map` (\n  `case_id` int(11) DEFAULT NULL,\n  `client_id` int(11) DEFAULT NULL,\n  `advocator_id` int(11) DEFAULT NULL,\n  `prosecutor_id` int(11) DEFAULT NULL,\n  KEY `case_id` (`case_id`),\n  KEY `client_id` (`client_id`),\n  KEY `advocator_id` (`advocator_id`),\n  KEY `prosecutor_id` (`prosecutor_id`)\n) ENGINE = MyISAM DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: prosecutor\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `prosecutor` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) DEFAULT NULL,\n  `address` varchar(255) DEFAULT NULL,\n  `role` varchar(50) DEFAULT 'prosecutor',\n  `status` varchar(50) DEFAULT 'active',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: prosecutor_documents\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `prosecutor_documents` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `description` text DEFAULT NULL,\n  `file_path` varchar(255) DEFAULT NULL,\n  `status` enum('pending', 'approved') DEFAULT 'pending',\n  `prosecutor_id` int(11) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `fk_prosecutor_id` (`prosecutor_id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 26 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: registrar\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `registrar` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `first_name` varchar(255) NOT NULL,\n  `last_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `phone_number` varchar(20) NOT NULL,\n  `address` varchar(255) NOT NULL,\n  `role` varchar(50) NOT NULL,\n  `status` varchar(50) DEFAULT 'Activated',\n  `image` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = MyISAM AUTO_INCREMENT = 50 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: reset_tokens\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `reset_tokens` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `email` varchar(100) NOT NULL,\n  `token` varchar(256) NOT NULL,\n  `expires` bigint(20) NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `email_unique` (`email`),\n  KEY `user_email_idx` (`email`),\n  CONSTRAINT `reset_tokens_ibfk_1` FOREIGN KEY (`email`) REFERENCES `users` (`email`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE = InnoDB AUTO_INCREMENT = 6 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: respondent_case_map\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `respondent_case_map` (\n  `case_id` int(11) DEFAULT NULL,\n  `client_id` int(11) DEFAULT NULL,\n  `advocator_id` int(11) DEFAULT NULL,\n  KEY `case_id` (`case_id`),\n  KEY `client_id` (`client_id`),\n  KEY `advocator_id` (`advocator_id`)\n) ENGINE = MyISAM DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci;\n\n# ------------------------------------------------------------\n# SCHEMA DUMP FOR TABLE: services\n# ------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS `services` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `name` varchar(255) DEFAULT NULL,\n  `amount` bigint(20) DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`)\n) ENGI