    'fs',\n    'ts',\n    'fss@gmail.com',\n    '0912131415',\n    'fiche',\n    '$2b$10$VbVctFmt43m18PTOzJmxieXZ2V/2cgukPCXkRA59Fj/2UJczfTueC',\n    'Invoice_Clerk',\n    'C:/Users/Henok/fullproject/frontend/src/image/profile picture.png',\n    'Activated',\n    NULL\n  );\nINSERT INTO\n  `users` (\n    `id`,\n    `first_name`,\n    `last_name`,\n    `email`,\n    `phone_number`,\n    `address`,\n    `password`,\n    `role`,\n    `profile_picture`,\n    `status`,\n    `image`\n  )\nVALUES\n  (\n    49,\n    'besufekad',\n    'masresha',\n    'besufekadmasresha05@gmail.com',\n    '0921877883',\n    'Ethiopia',\n    '$2b$10$TMot24ir5pvczx4fQ1IFGuUApGkCwFyjMaWwcEfWzWyxLRbOT1cQO',\n    'Registrar',\n    'C:/Users/Henok/fullproject/frontend/src/image/profile picture.png',\n    'Activated',\n    NULL\n  );\nINSERT INTO\n  `users` (\n    `id`,\n    `first_name`,\n    `last_name`,\n    `email`,\n    `phone_number`,\n    `address`,\n    `password`,\n    `role`,\n    `profile_picture`,\n    `status`,\n    `image`\n  )\nVALUES\n  (\n    54,\n    'b',\n    'm',\n    'bestbesu08@gmail.com',\n    '0921877883',\n    'Ethiopia',\n    '$2b$10$N.bYubnsT7/J7M99APO6Xe0XNDAFwpLaVFfiRlsGmyoDezRTDHifa',\n    'Invoice_Clerk',\n    'C:/Users/Henok/fullproject/frontend/src/image/profile picture.png',\n    'Activated',\n    NULL\n  );\n\n# ------------------------------------------------------------\n# DATA DUMP FOR TABLE: users_judge_type\n# ------------------------------------------------------------\n\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (1, 'Civil', 20);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (2, 'Civil', 22);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (3, 'Civil', 24);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (4, 'Criminal', 25);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (5, 'Criminal', 26);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (6, 'Criminal', 31);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (7, 'Civil', 46);\nINSERT INTO\n  `users_judge_type` (`id`, `judge_type`, `judge_id`)\nVALUES\n  (8, 'Criminal', 47);","trigger":"# ------------------------------------------------------------\n# TRIGGER DUMP FOR: after_insert_user\n# ------------------------------------------------------------\n\nDROP TRIGGER IF EXISTS after_insert_user;\nDELIMITER ;;\nCREATE TRIGGER `after_insert_user` AFTER INSERT ON `users` FOR EACH ROW BEGIN\n    IF NEW.role = 'registrar' THEN\n        INSERT INTO registrar (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\n\n    IF NEW.role = 'judge' THEN\n        INSERT INTO judge (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\n\n    IF NEW.role = 'prosecutor' THEN\n        INSERT INTO prosecutor (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\n\n    IF NEW.role = 'admin' THEN\n        INSERT INTO admin (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\n\n    IF NEW.role = 'court_manager' THEN\n        INSERT INTO court_manager (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\n\n    IF NEW.role = 'invoice_clerk' THEN\n        INSERT INTO invoice_clerk (id, first_name, last_name, email, phone_number, address, role, status, image)\n        VALUES (NEW.id, NEW.first_name, NEW.last_name, NEW.email, NEW.phone_number, NEW.address, NEW.role, NEW.status, NEW.image);\n    END IF;\nEND;;\nDELIMITER ;"}